<div class="va-shop-page"><div class="va-static-hero"><div><span>Your selections</span><h1>Cart</h1></div><nav><a href="<?= base_url() ?>">Home</a> / Cart</nav></div><?php if (empty($shop_items)): ?><div class="va-shop-empty"><i class="bi bi-bag"></i><h2>Your cart is empty</h2><a class="btn va-why-button" href="<?= base_url('accessories') ?>">Continue Shopping</a></div><?php else: ?><div class="va-cart-layout"><section><h2>Cart Summary</h2><div class="va-cart-table"><div class="va-cart-row va-cart-head"><span>Product</span><span>Price</span><span>Quantity</span><span>Subtotal</span></div><?php foreach ($shop_items as $item): $url=base_url('accessory/'.$item->id.'/'.$item->slug); ?><div class="va-cart-row"><div class="va-cart-product"><button class="shop-action va-remove" data-action="remove-cart" data-product-id="<?= $item->id ?>">×</button><?php if ($item->primary_image): ?><img src="<?= $item->primary_image ?>" alt=""><?php endif; ?><a href="<?= $url ?>"><?= html_escape($item->name) ?></a></div><span>&#8377; <?= number_format($item->price) ?></span><div class="va-cart-qty"><button class="cart-quantity" data-product-id="<?= $item->id ?>" data-change="-1">−</button><b><?= $item->quantity ?></b><button class="cart-quantity" data-product-id="<?= $item->id ?>" data-change="1">+</button></div><strong>&#8377; <?= number_format($item->price*$item->quantity) ?></strong></div><?php endforeach; ?></div><div class="va-cart-benefits"><div><i class="bi bi-heart-fill"></i><b>Loved by Thousands</b><span>Quality products for every vehicle.</span></div><div><i class="bi bi-arrow-repeat"></i><b>Easy Returns</b><span>Helpful support when you need it.</span></div><div><i class="bi bi-gift"></i><b>Order Now & Get Gift</b><span>Special offers on selected parts.</span></div></div></section><aside class="va-order-summary"><h2>Cart totals</h2><p><span>Subtotal</span><strong>&#8377; <?= number_format($total) ?></strong></p><p><span>Shipping</span><b>Free shipping</b></p><p class="va-order-total"><span>Total</span><strong>&#8377; <?= number_format($total) ?></strong></p><a href="<?= base_url('checkout') ?>" class="btn va-why-button w-100">Proceed to Checkout</a></aside></div><?php endif; ?></div>
